#include <bits/stdc++.h>
using namespace std;

string toString(__int128 v) {
    if (v == 0) return "0";
    bool neg = v < 0;
    unsigned __int128 u = neg ? -(unsigned __int128)v : (unsigned __int128)v;
    string s;
    while (u) { s += char('0' + u % 10); u /= 10; }
    if (neg) s += '-';
    reverse(s.begin(), s.end());
    return s;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n = 0;
    cin >> n;
    vector<long long> a(n);
    for (auto &x : a) cin >> x;
    vector<int> st;
    __int128 answer = 0;
    // Each element owns the subarrays where it is the rightmost maximum:
    // left boundary at a strictly greater value, right boundary at a value >= it.
    for (int i = 0; i <= n; i++) {
        while (!st.empty() && (i == n || a[st.back()] <= a[i])) {
            int j = st.back(); st.pop_back();
            long long left = j - (st.empty() ? -1 : st.back()), right = i - j;
            long long lengths = left * right * (left + right) / 2;  // sum of lengths of those subarrays
            answer += (__int128)a[j] * lengths;
        }
        st.push_back(i);
    }
    cout << toString(answer) << "\n";
}

import java.io.*;
import java.math.BigInteger;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        int[] st = new int[n + 1];
        int top = 0;
        BigInteger answer = BigInteger.ZERO;
        // Each element owns the subarrays where it is the rightmost maximum:
        // left boundary at a strictly greater value, right boundary at a value >= it.
        for (int i = 0; i <= n; i++) {
            while (top > 0 && (i == n || a[st[top - 1]] <= a[i])) {
                int j = st[--top];
                long left = j - (top > 0 ? st[top - 1] : -1), right = i - j;
                long lengths = left * right * (left + right) / 2;  // sum of lengths of those subarrays
                answer = answer.add(BigInteger.valueOf(a[j]).multiply(BigInteger.valueOf(lengths)));
            }
            st[top++] = i;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"math/big"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	st := make([]int, 0, n+1)
	answer := new(big.Int)
	term := new(big.Int)
	// Each element owns the subarrays where it is the rightmost maximum:
	// left boundary at a strictly greater value, right boundary at a value >= it.
	for i := 0; i <= n; i++ {
		for len(st) > 0 && (i == n || a[st[len(st)-1]] <= a[i]) {
			j := st[len(st)-1]
			st = st[:len(st)-1]
			prev := -1
			if len(st) > 0 {
				prev = st[len(st)-1]
			}
			left, right := int64(j-prev), int64(i-j)
			lengths := left * right * (left + right) / 2 // sum of lengths of those subarrays
			term.SetInt64(a[j])
			term.Mul(term, big.NewInt(lengths))
			answer.Add(answer, term)
		}
		st = append(st, i)
	}
	fmt.Println(answer.String())
}
